bash_commands:
cat lgb_probe.log 2>/dev/null; echo "---"; ../../.venv/bin/python -c "
import holidays
print(holidays.__version__)
de = holidays.Germany(years=[2019,2020])
for d,n in sorted(de.items()):
    if d.month==1 or d.month==12: print(d, d.strftime('%a'), n)
print('--- subdiv BY (Bavaria) 2020 Jan/Dec:')
by = holidays.Germany(years=[2020], subdiv='BY')
for d,n in sorted(by.items()):
    if d.month in (1,12): print(d, d.strftime('%a'), n)
"
